// NOVEL (hand-authored) — not generated by CLI Printing Press.
// Recorded in .printing-press-patches/garmin-windowed-sync.json.
//
// What a run will cost, answered from the archive alone.
//
// Every number `history --status`, `history --dry-run` and the estimate line
// print comes from here, and none of them makes a single API call: the state
// table says how far each series is filled, the archive says which days carry
// a reading and how large a row of each series is, and the catalog says how
// many days one request covers. That is enough to say "about this many
// requests, about this long, up to this much disk" before the expensive part
// of a run starts, which is the whole point — the caller finds out what a full
// fill costs before paying for it rather than after.
//
// pp:data-source local

package cli

import (
	"fmt"
	"sort"
	"time"

	"github.com/mvanhorn/printing-press-library/library/health/garmin/internal/store"
)

// garminSignalResources are the cheap series whose stored days say a wearable
// was recording that day. A per-day series — one request per date, and up to
// 88 KB a night — is walked over these days and the days an activity started
// on, never over the calendar (N131 decision D15).
//
// intensity_minutes is deliberately absent: it answers weekly, with null-
// valued rows stretching back to 2007 on both reference accounts, so its days
// are a property of the endpoint rather than evidence anybody was wearing
// anything.
var garminSignalResources = []string{"steps", "resting_hr", "sleep_stats", "sleep_score", "max_metrics"}

// garminActivityDayField is the activity payload field that carries the day an
// activity started. walkActivities keys its rows by this same constant, so the
// day a signal set derives from an activity and the day the feed bookmarks by
// cannot drift apart.
const garminActivityDayField = "startTimeLocal"

// garminObservedLatency is how long one Garmin request takes on top of the
// pacing delay: 130 ms, the round-trip observed across the live runs recorded
// in N131 §9. It is only ever used to turn a request count into a duration a
// human can decide on.
const garminObservedLatency = 130 * time.Millisecond

// garminMeasuredBytesMinRows is how many rows a series must already hold
// before this archive's own mean row size replaces the constant below. Under
// thirty rows the mean swings with a single outlier night.
const garminMeasuredBytesMinRows = 30

// garminSeriesRowBytes is the mean stored size of one row of each series,
// measured 2026-09-13 over the reference archive (row counts in the comments).
// They are a starting point only: once a series holds garminMeasuredBytesMinRows
// rows, the estimate uses that archive's own average instead.
var garminSeriesRowBytes = map[string]int{
	"steps":              85,    // 2 260 rows
	"resting_hr":         42,    // 2 260 rows
	"sleep_stats":        559,   // 2 015 rows
	"sleep_score":        39,    // 1 679 rows
	"max_metrics":        734,   // 446 rows
	"intensity_minutes":  87,    // 1 028 rows
	"activities":         3865,  // 3 255 rows
	"activity_detail":    3327,  // 1 000 rows
	"activity_splits":    2666,  // 1 000 rows
	"activity_hr_zones":  358,   // 761 rows
	"hr_zone_config":     1180,  // 1 row
	"daily_summary":      2666,  // 90 rows
	"daily_hr":           12977, // 90 rows
	"sleep_detail":       88340, // 90 rows
	"training_readiness": 1024,  // no rows in either reference archive; nominal
}

// garminSeriesPlan is one series' state and its outstanding work. It is what
// --status prints, what --dry-run prints, and what the estimate line adds up.
type garminSeriesPlan struct {
	Series       string `json:"series"`
	Kind         string `json:"kind"`
	Rows         int    `json:"rows"`
	Earliest     string `json:"earliest_day,omitempty"`
	LastComplete string `json:"last_complete_day,omitempty"`
	StopReason   string `json:"stop_reason,omitempty"`
	// Outstanding is how many requests this series still owes. -1 means the
	// count cannot be known without asking Garmin, which is true of exactly
	// one series: the activity feed, whose length is on the server.
	Outstanding int    `json:"outstanding"`
	Bytes       int64  `json:"bytes"`
	Since       string `json:"since,omitempty"`
	Note        string `json:"note,omitempty"`
}

// garminWorkEstimate is the one line printed before the expensive half of a
// run, and the whole of what --dry-run reports.
type garminWorkEstimate struct {
	Since     string  `json:"since,omitempty"`
	Requests  int     `json:"requests"`
	Minutes   float64 `json:"minutes"`
	Megabytes float64 `json:"megabytes"`
}

func (e garminWorkEstimate) line() string {
	if e.Requests <= 0 {
		return "Nothing left to fetch: every series is filled through yesterday."
	}
	since := e.Since
	if since == "" {
		since = "the start of this account's history"
	}
	unit := "requests"
	if e.Requests == 1 {
		unit = "request"
	}
	// The date is where the archive ENDS UP, not where this run starts: a
	// caught-up archive owes a handful of requests while still covering years,
	// and "fetching everything since 2007" would have been a lie about both.
	return fmt.Sprintf("About %d %s, %s, up to %.0f MB — after which the archive covers %s to today.",
		e.Requests, unit, garminHumanMinutes(e.Minutes), e.Megabytes, since)
}

// garminHumanMinutes phrases a duration whole, hedge included, so no caller
// has to prefix one and none can produce "about under a minute".
func garminHumanMinutes(m float64) string {
	switch {
	case m < 1:
		return "under a minute"
	case m < 60:
		return fmt.Sprintf("about %.0f min", m)
	default:
		return fmt.Sprintf("about %.1f h", m/60)
	}
}

// garminPlanner answers the cost questions from the archive. It holds no
// client, which is how "--dry-run makes no traffic" is a structural fact
// rather than a promise: there is nothing here to make a request with.
type garminPlanner struct {
	db            *store.Store
	depth         garminDepth
	now           func() time.Time
	loc           *time.Location
	delay         time.Duration
	maxDependents int

	signalCache  []civilDay
	signalLoaded bool
}

func (p *garminPlanner) today() civilDay { return today(p.now, p.loc) }

func (p *garminPlanner) ceiling() civilDay { return completeDayCeiling(p.today()) }

// garminSeriesFilled reports whether a state row describes a filled range this
// walk can resume from. A row written before store.GarminWalkVersion was
// written by the retired backward walk, whose last_complete_day was the top of
// a range walked downwards rather than the top of a contiguous fill, so it is
// read as unfilled and re-walked once. Rows already stored are not re-fetched
// — the walk skips a day that has one — so the cost is windows, not payloads.
func garminSeriesFilled(st store.GarminSeriesState) bool {
	return st.WalkVersion >= store.GarminWalkVersion && st.EarliestDay != "" && st.LastCompleteDay != ""
}

// signalDays is every day the archive shows a reading for, oldest first: a row
// in one of the cheap day-keyed series, or the start day of a stored activity.
func (p *garminPlanner) signalDays() ([]civilDay, error) {
	if p.signalLoaded {
		return p.signalCache, nil
	}
	seen := map[civilDay]bool{}
	ids, err := p.db.DistinctResourceIDs(garminSignalResources)
	if err != nil {
		return nil, err
	}
	for _, id := range ids {
		if d, ok := dayFromValue(id); ok {
			seen[d] = true
		}
	}
	starts, err := p.db.ResourceJSONFieldValues("activities", garminActivityDayField)
	if err != nil {
		return nil, err
	}
	for _, v := range starts {
		if d, ok := dayFromValue(v); ok {
			seen[d] = true
		}
	}
	out := make([]civilDay, 0, len(seen))
	for d := range seen {
		out = append(out, d)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].before(out[j]) })
	p.signalCache, p.signalLoaded = out, true
	return out, nil
}

// windowedFloor is the oldest day a windowed series will be asked for on this
// run. --since raises it; a plain run on an already-filled series keeps the
// depth the archive has.
func (p *garminPlanner) windowedFloor(s garminSeries, st store.GarminSeriesState) civilDay {
	switch p.depth.mode {
	case depthFrom:
		return maxDay(p.depth.day, s.floor)
	case depthAll:
		return s.floor
	default:
		if garminSeriesFilled(st) {
			return mustDay(st.EarliestDay)
		}
		return s.floor
	}
}

// perDayFloor is the oldest day a per-day series will be asked for. A zero day
// means "every signal day the archive knows", which is what a full fill wants.
func (p *garminPlanner) perDayFloor(st store.GarminSeriesState) civilDay {
	switch p.depth.mode {
	case depthFrom:
		return p.depth.day
	case depthAll:
		return civilDay{}
	default:
		if garminSeriesFilled(st) {
			return mustDay(st.EarliestDay)
		}
		return civilDay{}
	}
}

// garminPerDayWork is what one per-day series owes: the days to request, in
// ascending order, and the oldest day the run will have covered when it ends.
type garminPerDayWork struct {
	days      []civilDay
	coverFrom civilDay
	refresh   map[string]bool
}

func (p *garminPlanner) perDayWork(s garminSeries, st store.GarminSeriesState) (garminPerDayWork, error) {
	signal, err := p.signalDays()
	if err != nil {
		return garminPerDayWork{}, err
	}
	filled := garminSeriesFilled(st)
	floor := p.perDayFloor(st)
	if !s.floor.isZero() && !floor.isZero() && floor.before(s.floor) {
		floor = s.floor
	}
	earliest := mustDay(st.EarliestDay)
	last := mustDay(st.LastCompleteDay)
	now := p.today()
	ceiling := p.ceiling()

	considered := make([]civilDay, 0, len(signal))
	for _, d := range signal {
		if !floor.isZero() && d.before(floor) {
			continue
		}
		if d.after(now) {
			continue
		}
		considered = append(considered, d)
	}

	// A series with no signal day at all has nothing to cover: leaving
	// coverFrom zero is what keeps the walk from stamping a filled range at
	// today and pinning every later plain run above the days the archive has
	// yet to learn about.
	work := garminPerDayWork{refresh: map[string]bool{}, coverFrom: floor}
	if work.coverFrom.isZero() && len(considered) > 0 {
		work.coverFrom = considered[0]
	}

	// The refresh window: the newest complete signal days inside the filled
	// range. Outside it every day is new work already.
	if filled {
		count := 0
		for i := len(considered) - 1; i >= 0 && count < garminRefreshDays; i-- {
			d := considered[i]
			if d.after(ceiling) || d.after(last) || d.before(earliest) {
				continue
			}
			work.refresh[d.String()] = true
			count++
		}
	}

	ids := make([]string, 0, len(considered))
	for _, d := range considered {
		ids = append(ids, d.String())
	}
	missingIDs, err := p.db.MissingResourceIDs(s.resource, ids)
	if err != nil {
		return garminPerDayWork{}, err
	}
	missing := make(map[string]bool, len(missingIDs))
	for _, id := range missingIDs {
		missing[id] = true
	}

	for _, d := range considered {
		key := d.String()
		if work.refresh[key] {
			work.days = append(work.days, d)
			continue
		}
		inFilled := filled && !d.before(earliest) && !d.after(last)
		if !inFilled && missing[key] {
			work.days = append(work.days, d)
		}
	}
	return work, nil
}

// rowBytes is the mean size of one row of a series: this archive's own average
// once it has enough rows to mean something, and the measured constant before
// that.
func (p *garminPlanner) rowBytes(resource string) int {
	if avg, rows, err := p.db.AverageResourceBytes(resource); err == nil && rows >= garminMeasuredBytesMinRows && avg > 0 {
		return avg
	}
	return garminSeriesRowBytes[resource]
}

// seriesPlan is one series' state plus what it still owes.
func (p *garminPlanner) seriesPlan(s garminSeries) (garminSeriesPlan, error) {
	st, err := p.db.GetGarminSeriesState(s.name)
	if err != nil {
		return garminSeriesPlan{}, err
	}
	rows, err := p.db.CountResourceRows(s.resource)
	if err != nil {
		return garminSeriesPlan{}, err
	}
	plan := garminSeriesPlan{
		Series:       s.name,
		Kind:         kindName(s.kind),
		Rows:         rows,
		Earliest:     st.EarliestDay,
		LastComplete: st.LastCompleteDay,
		StopReason:   st.StopReason,
	}
	// A row from the retired backward walk describes a range this walk
	// cannot resume from, so reporting its days as a filled range would
	// promise coverage the next run is about to go and fetch. The row count
	// is real and stays; the range is replaced by what is actually true.
	if st.WalkVersion < store.GarminWalkVersion && (st.EarliestDay != "" || st.LastCompleteDay != "") {
		plan.Earliest, plan.LastComplete = "", ""
		plan.StopReason = "state predates this walk; re-walks once"
	}
	bytesPerRow := int64(p.rowBytes(s.resource))
	now := p.today()

	switch s.kind {
	case seriesWindowed:
		floor := p.windowedFloor(s, st)
		plan.Since = floor.String()
		requests := 0
		if garminSeriesFilled(st) {
			earliest := mustDay(st.EarliestDay)
			if floor.before(earliest) {
				requests += len(planForwardWindows(floor, earliest.addDays(-1), s.windowDays))
			}
			requests += len(planForwardWindows(mustDay(st.LastCompleteDay).addDays(1), now, s.windowDays))
		} else {
			requests = len(planForwardWindows(floor, now, s.windowDays))
		}
		plan.Outstanding = requests
		plan.Bytes = int64(requests) * int64(s.windowDays) * bytesPerRow
	case seriesPerDay:
		work, workErr := p.perDayWork(s, st)
		if workErr != nil {
			return garminSeriesPlan{}, workErr
		}
		plan.Since = work.coverFrom.String()
		plan.Outstanding = len(work.days)
		plan.Bytes = int64(len(work.days)) * bytesPerRow
		plan.Note = "one request per day a wearable recorded something"
	case seriesOffsetPaged:
		plan.Outstanding = -1
		plan.Note = "pages until the feed ends; the page count is on the server"
		if garminSeriesFilled(st) {
			plan.Since = st.EarliestDay
		}
		if p.depth.mode == depthFrom {
			plan.Since = p.depth.day.String()
		}
	case seriesPerParent:
		parents, parentErr := p.db.ResourceIDsNewestFirst(s.parentResource, 0)
		if parentErr != nil {
			return garminSeriesPlan{}, parentErr
		}
		missing, missingErr := p.db.MissingResourceIDs(s.resource, parents)
		if missingErr != nil {
			return garminSeriesPlan{}, missingErr
		}
		outstanding := len(missing)
		if p.maxDependents > 0 && outstanding > p.maxDependents {
			outstanding = p.maxDependents
		}
		plan.Outstanding = outstanding
		plan.Bytes = int64(outstanding) * bytesPerRow
		plan.Note = "one request per " + s.parentNoun + " with no row yet"
	case seriesSingleDocument:
		plan.Outstanding = 1
		plan.Bytes = bytesPerRow
		plan.Note = "one request for the whole account"
	}
	return plan, nil
}

// garminEstimateOf adds a set of series plans into the one line a caller
// decides on. Requests that cannot be counted (the feed) are left out of the
// total and named in the line's absence rather than guessed at.
func garminEstimateOf(plans []garminSeriesPlan, depth garminDepth, delay time.Duration) garminWorkEstimate {
	est := garminWorkEstimate{}
	var bytes int64
	since := civilDay{}
	for _, plan := range plans {
		if plan.Outstanding > 0 {
			est.Requests += plan.Outstanding
			bytes += plan.Bytes
			if d, err := parseCivilDay(plan.Since); err == nil {
				since = minDay(since, d)
			}
		}
	}
	if depth.mode == depthFrom {
		since = depth.day
	}
	est.Since = since.String()
	est.Minutes = float64(est.Requests) * float64(delay+garminObservedLatency) / float64(time.Minute)
	est.Megabytes = float64(bytes) / 1e6
	return est
}
